mapper.select:
SELECT name AS "name", spec AS "spec", COALESCE(stock_qty, 0) AS "stockQty"
FROM products
WHERE code = #{code}

mapper.update:
UPDATE products
SET stock_qty = #{stockQty,jdbcType=DOUBLE}
WHERE code = #{code}

mapper.insert:
INSERT INTO product_stock_movement (
    product_code, product_name, moved_on, kind, qty, balance_after,
    source_table, source_id, client_code, note, created_by, created_at
) VALUES (
    #{productCode}, #{productName}, #{movedOn}, #{kind}, #{qty,jdbcType=DOUBLE}, #{balanceAfter,jdbcType=DOUBLE},
    #{sourceTable}, #{sourceId,jdbcType=INTEGER},
    (SELECT c.client_code FROM clients c WHERE c.name = #{clientName} AND NULLIF(c.client_code, '') IS NOT NULL ORDER BY c.client_code LIMIT 1),
    #{note}, #{createdBy}, #{createdAt}
)

mapper.select:
SELECT name
FROM materials
WHERE code = #{code}

mapper.update:
UPDATE materials
SET stock_qty = COALESCE(stock_qty, 0) + #{delta,jdbcType=DOUBLE}
WHERE code = #{code}
